{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/media-list.json
    A list or figures beside a picture. Axes: layout (figures: four figures in two columns, proof: three figures and a featured review, steps: numbered steps, posts: the latest posts, topics: topic rows with counts, contact: contact buttons and support figures), mediaSide, tone. The actions follow every layout but contact.
    Props (p): id, title, lead, badge, extras, labels, actions, layout, mediaSide, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_extras = ($p['extras'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'figures')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_1}
  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => (og_t(og_or([og_eq($v_layout, 'steps'), og_eq($v_layout, 'topics')])) ? '1/1' : '4/3')]])|noescape}
{/capture}
{capture $c_2}
  {if og_t(og_or([og_eq($v_layout, 'figures'), og_eq($v_layout, 'proof')]))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['stats'])), 0))}
      {=og_include('blocks/media-figures.latte', ['p' => ['extras' => $v_extras, 'mode' => (og_t(og_eq($v_layout, 'proof')) ? 'row' : 'grid')]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'proof'))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['reviews'])), 0))}
      {=og_include('blocks/media-review.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'steps'))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['steps'])), 0))}
      {=og_include('blocks/media-steps.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'posts'))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['posts'])), 0))}
      {=og_include('blocks/media-posts.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'topics'))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['topics'])), 0))}
      {=og_include('blocks/media-topics.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'contact'))}
    {if og_t(og_gt(og_len(og_get($v_extras, ['channels'])), 0))}
      {=og_include('blocks/media-contacts.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
    {/if}
  {/if}
  {if og_t(!(og_eq($v_layout, 'contact')))}
    {=og_include('blocks/action-group.latte', ['p' => ['primary' => og_get($v_actions, ['cta']), 'primaryHref' => og_get($v_actions, ['href']), 'secondary' => (og_t(og_eq(og_get($v_actions, ['mode']), 'two')) ? og_get($v_actions, ['secondary']) : null), 'secondaryHref' => og_get($v_actions, ['secondaryHref'])]])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => og_markup($f_1)], 'children' => og_markup($c_2)])|noescape}
